shell('submission-ready.html','Final submission review',heading('FINAL REVIEW','Send only when everything is ready.','Your payment is recorded. Your proposal has not been sent to the insurer.')+'''<div class="two-column"><section class="document"><h2>Before you submit</h2><ul class="plain-list"><li>Required details and disclosures are complete.</li><li>Suggested document values have been confirmed.</li><li>The current quote, options and terms have been reviewed.</li><li>Payment and any balance or refund are reconciled.</li></ul><label class="check"><input type="checkbox"> I have reviewed this proposal revision and want to submit it.</label><p>Any change reopens the affected review. Payment alone does not activate cover.</p><a class="button" href="timeline.html">Preview submitted state</a></section><aside class="sticky-panel"><h2>Still want to make a change?</h2><a class="button secondary" href="onboarding.html">Edit onboarding</a><a class="text-link" href="cancel-before.html">Cancel before submission</a><p>Nothing is sent from this wireframe.</p></aside></div>''','SCR-SUBMIT/READY',[3,12,28,32,49],4,True)

shell('submission-blocked.html','Submission needs completion',heading('BEFORE SUBMISSION','Finish these steps first.','Your proposal stays with the marketplace while you complete onboarding.')+notice('Not sent to the insurer','An unresolved disclosure, unreviewed change or pending payment adjustment prevents submission.','yellow')+'''<section class="paper-panel"><h2>Next action</h2><p>Review the incomplete or changed item. Your previous answers and payment history are retained.</p><a class="button" href="onboarding.html">Resume onboarding</a><a class="text-link" href="refund-unknown.html">Check a pending adjustment</a></section>''','SCR-SUBMIT/BLOCKED',[3,28,32,49],4,True,'Incomplete')

shell('refund-choice.html','Choose refund destination',heading('REFUND / CHOOSE DESTINATION','Where would you like the refund?','Arithmetic fixture: ₹400 is eligible for this simulated refund.')+'''<section class="document"><fieldset><legend>Refund destination</legend><label class="check"><input type="radio" name="refund-destination"> Original payment method</label><p>Proposed estimate: 3–5 business days after provider acceptance. Track the actual status; timing is not a verified provider guarantee.</p><label class="check"><input type="radio" name="refund-destination"> Marketplace wallet</label><p>Mock credit appears instantly after confirmation succeeds. It can be used in mock checkout. No real money is held.</p></fieldset><p>Choose one destination. A pending original-method refund must be reconciled before a different route can be used.</p><div class="actions"><a class="button secondary" href="refund-origin.html">Preview original-method refund</a><a class="button secondary" href="wallet-credit.html">Preview confirmed wallet credit</a></div></section>''','SCR-REFUND/DESTINATION',[4,12,30,32,49],4,True)

shell('refund-origin.html','Original-method refund pending',heading('REFUND / ORIGINAL PAYMENT METHOD','Your refund is being processed.','Arithmetic fixture · ₹400 · MOCK-REFUND-01')+notice('Proposed estimate: 3–5 business days','The estimate starts after provider acceptance and uses the configured business-day calendar. This preview does not promise a real provider completion date.','blue')+'''<section class="paper-panel"><h2>One refund. One reference.</h2><p>Keep the original payment and refund references together. Do not start another refund while the outcome is pending.</p><div class="actions"><a class="button secondary" href="refund-complete.html">Confirmed state</a><a class="text-link" href="refund-failed.html">Failed state</a><a class="text-link" href="refund-unknown.html">Outcome unknown</a></div></section>''','SCR-REFUND/ORIGIN',[4,12,32,49],4,True,'Pending')

shell('wallet-credit.html','Wallet credit confirmed',heading('WALLET / SIMULATED CREDIT','₹400 added to your mock wallet.','The credit is confirmed. It is not a real stored-value balance.')+'''<section class="document"><dl class="definition-list"><div><dt>Adjustment reference</dt><dd>MOCK-ADJUSTMENT-01</dd></div><div><dt>Destination</dt><dd>Marketplace mock wallet</dd></div><div><dt>Credit status</dt><dd>Confirmed</dd></div><div><dt>Original-method refund</dt><dd>Not requested for this amount</dd></div></dl><a class="button" href="wallet.html">View wallet and history</a><a class="text-link" href="onboarding.html">Return to application</a></section>''','SCR-WALLET/CREDIT',[4,10,12,32,49],4,True,'Confirmed')

shell('wallet.html','Wallet balance and history',heading('YOUR ACCOUNT / MOCK WALLET','Your balance, with its history.','Only simulated funds appear in this preview.')+'''<div class="two-column"><section class="document"><p class="eyebrow">AVAILABLE MOCK BALANCE</p><h2>₹400</h2><p>No reservation is pending in this fixed example.</p><div class="table-wrap"><table><thead><tr><th>Entry</th><th>Amount</th><th>Status</th></tr></thead><tbody><tr><td>Application adjustment<br>MOCK-ADJUSTMENT-01</td><td>+₹400</td><td>Confirmed credit</td></tr></tbody></table></div></section><aside class="sticky-panel"><h2>Use it deliberately.</h2><p>Review the order and choose whether to apply wallet credit. A reservation prevents spending the same balance twice.</p><a class="button secondary" href="wallet-checkout.html">Preview wallet at checkout</a><a class="text-link" href="home-signed-in.html">Back to account</a></aside></div>''','SCR-WALLET/HISTORY',[4,10,12,32,49],3,True)

shell('wallet-checkout.html','Apply wallet credit at checkout',heading('PAYMENT / MOCK WALLET','Choose how much credit to apply.','An arithmetic fixture illustrates payment allocation; no insurer price is quoted.')+'''<section class="document"><dl class="definition-list"><div><dt>Fixture order total</dt><dd>₹10,000</dd></div><div><dt>Available mock wallet</dt><dd>₹400</dd></div><div><dt>If full credit is applied</dt><dd>₹400 wallet + ₹9,600 mock gateway</dd></div></dl><label class="check"><input type="checkbox"> Apply ₹400 of mock wallet credit</label><p>The wallet reservation and gateway balance must belong to the same order. An uncertain payment is reconciled before releasing or reusing the reservation.</p><a class="button secondary" href="payment.html">Preview remaining gateway payment</a><a class="text-link" href="payment-unknown.html">Preview uncertain payment</a></section>''','SCR-WALLET/CHECKOUT',[4,10,12,31,32,49],3,True)

shell('cancel-before.html','Cancel before proposal submission',heading('CANCELLATION / NOT SUBMITTED','Cancel this application?','The proposal has not been sent to the insurer in this scenario.')+'''<section class="document"><h2>Review what will happen</h2><p>On confirmation, the application stops and cannot be sent for insurer review. Your payment history remains available.</p><p>Any refundable amount must be verified from the payment and application record. An unknown amount is not a refund promise.</p><label class="check"><input type="checkbox"> I want to cancel this unsubmitted application.</label><div class="actions"><a class="button" href="cancelled.html">Preview confirmed cancellation</a><a class="button secondary" href="onboarding.html">Keep application</a></div></section>''','SCR-CANCEL/BEFORE',[3,5,12,28,36,49],4,True)

shell('cancelled.html','Application cancelled',heading('CANCELLATION / CONFIRMED','Your application has stopped.','No proposal will be sent from this simulated unsubmitted application.')+'''<section class="paper-panel"><h2>Next: check the refund</h2><p>Cancellation and refund completion are separate. Choose a destination only after the refundable amount is verified.</p><a class="button secondary" href="refund-choice.html">Preview refund options</a><a class="text-link" href="home-signed-in.html">Back to account</a></section>''','SCR-CANCEL/CONFIRMED',[5,12,32,36,49],4,True,'Cancelled')

shell('cancel-after.html','Cancellation after insurer submission',heading('CANCELLATION / SUBMITTED','Please contact the insurer to request cancellation.','The proposal has already been sent. The marketplace has not cancelled it.')+notice('Use the insurer’s verified contact route','The final screen must show the source-verified contact method, application reference and relevant policy/process information. No contact route has been supplied for this preview.','paper')+'''<section class="paper-panel"><h2>Keep the record handy</h2><p>Retain your application, payment and submission reference. Cancellation eligibility and refund handling depend on the insurer’s applicable process.</p><button disabled>Open verified insurer contact</button><a class="text-link" href="help.html">Help finding the contact route</a><a class="text-link" href="timeline.html">View submission record</a></section>''','SCR-CANCEL/AFTER',[5,12,34,36,49],5,True,'Insurer handles request')

shell('cancel-unknown.html','Check submission before cancellation',heading('CANCELLATION / VERIFYING SUBMISSION','We need to confirm whether it was sent.','The insurer submission outcome is uncertain.')+notice('Your request needs reconciliation','An unknown submission cannot be treated as an unsubmitted application. Check the existing reference before sending again or confirming cancellation.','yellow')+'''<div class="actions"><a class="button secondary" href="timeline.html">View current status</a><a class="text-link" href="help.html">Get help</a></div>''','SCR-CANCEL/UNKNOWN',[5,12,28,35,36,49],5,True,'Unknown dispatch')

shell('renewal.html','Review policy renewal',heading('RENEWAL / BEFORE EXPIRY','Keep the next policy period in view.','Review a fresh offer before your current policy expires.')+'''<div class="two-column"><section class="document"><h2>Current policy</h2><dl class="definition-list"><div><dt>Expiry date</dt><dd>Verified policy date required</dd></div><div><dt>Existing cover and options</dt><dd>Current policy version retained</dd></div><div><dt>Renewal premium</dt><dd>Fresh quote required</dd></div><div><dt>Mandate status</dt><dd>No active mandate in this scenario</dd></div></dl><p>A renewal is a new linked application. The existing policy remains available.</p><a class="button" href="renewal-review.html">Review renewal details</a></section><aside class="sticky-panel"><h2>No mandate? Review and pay.</h2><p>You can make a direct payment after confirming the renewal offer. This reminder cannot charge you.</p><a class="button secondary" href="renewal-nudge.html">Preview payment reminder</a><a class="text-link" href="renewal-expired.html">Already expired?</a></aside></div>''','SCR-RENEW/START',[5,26,31,36,49],1,True)

shell('renewal-review.html','Review renewal details and options',heading('RENEWAL / DETAIL REVIEW','Confirm what stayed the same—and what changed.','Use the new quote and effective dates for the renewal period.')+'''<section class="document"><div class="table-wrap"><table><thead><tr><th>Review</th><th>Current record</th><th>Renewal</th></tr></thead><tbody><tr><th>Address / PIN / rating details</th><td>Previously recorded details</td><td>Confirm or edit</td></tr><tr><th>Cover and add-ons</th><td>Current configuration</td><td>Recheck availability and eligibility</td></tr><tr><th>Price and terms</th><td>Historic accepted quote</td><td>Fresh source/version required</td></tr><tr><th>Effective period</th><td>Verified existing dates</td><td>New source-defined dates required</td></tr></tbody></table></div><p>Do not assume the old premium or benefits continue unchanged. Payment does not by itself establish renewed cover.</p><div class="actions"><a class="button secondary" href="quote-review.html">Review fresh renewal quote</a><a class="text-link" href="addons.html">Review optional cover</a></div></section>''','SCR-RENEW/REVIEW',[5,9,26,31,36,49],2,True)

shell('renewal-nudge.html','Renewal direct-payment reminder',heading('RENEWAL / PAYMENT REMINDER','Your renewal needs a payment decision.','No active mandate is recorded in this scenario.')+'''<section class="paper-panel"><h2>Review and pay directly</h2><p>Check the current renewal amount, terms and effective dates. Sign in if your session has expired. No automatic debit will be initiated by this reminder.</p><div class="actions"><a class="button" href="renewal-review.html">Review renewal and pay</a><a class="button secondary" href="policy.html">View existing policy</a><a class="text-link" href="renewal-mandate.html">Active-mandate state</a></div></section>''','SCR-RENEW/NO-MANDATE',[5,26,31,32,36,49],3,True,'Direct payment')

shell('renewal-mandate.html','Renewal mandate status',heading('RENEWAL / MOCK MANDATE','Check the recorded payment arrangement.','This preview has no real mandate or bank authorization.')+'''<section class="document"><h2>Active mock mandate</h2><p>Display its verified status, schedule, amount rule and source terms before any real use. An inactive, revoked or failed mandate returns to the direct-pay review.</p><p>If payment is uncertain, reconcile the existing attempt. If renewal is paid, suppress a duplicate payment nudge.</p><div class="actions"><a class="button secondary" href="payment-unknown.html">Payment outcome unknown</a><a class="text-link" href="renewal-nudge.html">Revoked or failed mandate</a><a class="text-link" href="renewal-paid.html">Renewal payment confirmed</a></div></section>''','SCR-RENEW/MANDATE',[5,12,31,32,36,49],3,True)

shell('renewal-paid.html','Renewal payment confirmed',heading('RENEWAL / MOCK PAYMENT CONFIRMED','Payment recorded. Follow the renewal application.','Do not pay again for this confirmed attempt.')+'''<section class="paper-panel"><h2>Complete the remaining steps</h2><p>Finish any required onboarding and review before the renewal proposal is sent. The current policy and renewal application stay linked; renewed coverage needs its own issuance/effective-date evidence.</p><a class="button" href="onboarding.html">Resume renewal onboarding</a><a class="text-link" href="timeline.html">View renewal status</a></section>''','SCR-RENEW/PAID',[5,12,27,31,32,36,49],4,True,'Paid, not yet issued')

